SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET @seed_now=CURRENT_TIMESTAMP();
SET @seed_day=CURRENT_DATE();
SET @seed_history_day=DATE_SUB(CURRENT_DATE(),INTERVAL IF(HOUR(CURRENT_TIMESTAMP())>=17,0,1) DAY);
SET @seed_admin_id=(SELECT u.user_id FROM sys_user u JOIN sys_role r ON r.role_id=u.role_id WHERE r.role_key='admin' AND u.status='0' ORDER BY u.user_id LIMIT 1);
SET @seed_admin_name=(SELECT COALESCE(NULLIF(nickname,''),username) FROM sys_user WHERE user_id=@seed_admin_id);
SET @seed_planner_id=(SELECT u.user_id FROM sys_user u JOIN sys_role r ON r.role_id=u.role_id WHERE r.role_key='planner' AND u.status='0' ORDER BY u.user_id LIMIT 1);
SET @seed_planner_name=(SELECT COALESCE(NULLIF(nickname,''),username) FROM sys_user WHERE user_id=@seed_planner_id);
SET @seed_operator_id=(SELECT u.user_id FROM sys_user u JOIN sys_role r ON r.role_id=u.role_id WHERE r.role_key='operator' AND u.status='0' ORDER BY u.user_id LIMIT 1);
