SET @seed_maintainer_id=(SELECT u.user_id FROM sys_user u JOIN sys_role r ON r.role_id=u.role_id WHERE r.role_key='maintainer' AND u.status='0' ORDER BY u.user_id LIMIT 1);
SET @seed_maintainer_name=(SELECT COALESCE(NULLIF(nickname,''),username) FROM sys_user WHERE user_id=@seed_maintainer_id);
SET @seed_stock_id=COALESCE((SELECT u.user_id FROM sys_user u JOIN sys_role r ON r.role_id=u.role_id WHERE r.role_key='warehouse' AND u.status='0' ORDER BY u.user_id LIMIT 1),@seed_admin_id);
