-- Derive before/after quantities chronologically from zero opening balances.
UPDATE wms_stock_flow f JOIN (SELECT flow_id, SUM(change_qty) OVER(PARTITION BY inventory_id ORDER BY create_time,flow_id ROWS UNBOUNDED PRECEDING) balance FROM wms_stock_flow) x ON x.flow_id=f.flow_id SET f.before_qty=x.balance-f.change_qty,f.after_qty=x.balance;
UPDATE wms_inventory i JOIN (SELECT inventory_id,SUM(change_qty) qty,MAX(create_time) last_time FROM wms_stock_flow GROUP BY inventory_id) x ON x.inventory_id=i.inventory_id SET i.qty=x.qty,i.update_time=x.last_time;
-- MySQL 8.0.16+: a nonzero violation count raises CHECK constraint failure.
-- Works after initialization and during normal workflow use; checks relationships, not fixed row counts.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
DROP TEMPORARY TABLE IF EXISTS demo_validation_result;
CREATE TEMPORARY TABLE demo_validation_result (check_name VARCHAR(80) PRIMARY KEY, violations BIGINT NOT NULL CHECK (violations=0));
SELECT check_name,violations FROM demo_validation_result ORDER BY check_name;
DROP TEMPORARY TABLE demo_validation_result;

COMMIT;
